import type { Unit } from "@/content/types";

// This unit is the ONE dedicated home for informal imperative grammar (tu/noi/voi).
// It intentionally does NOT teach the Lei formal imperative — that belongs to
// b1-unit-40-formal-register.ts (16 dedicated conjugation cards) with light
// reinforcement in b1-unit-27-health.ts. b1-unit-45-environment-nature.ts's own
// 10-card imperativo section (recycling/eco-tips context) is treated as light
// reinforcement of this unit going forward, not new teaching — this unit uses
// entirely different contexts (cooking, chores, directions, coaching, workplace,
// travel) and does not repeat any of its example sentences.
//
// Vocabulary note: "la scadenza" (b154-t1-027/028) is deliberately reinforced
// here (workplace theme) alongside its independent introduction in
// b1-unit-40-formal-register.ts (b140-t1-035/036, formal-letters theme). No
// sentence or hint is shared between the two — this is intentional repetition
// within CURRICULUM.md's tolerance for short vocabulary-phrase overlap between
// related units, not an oversight.

